import hashlib
from event_packet import EventPacket
from sequencer import sequence_stream_batch

def test_stream_sequencing():
    # Test case that was failing due to non-deterministic ordering
    p1 = EventPacket("s1", 5, "payload_a")
    p2 = EventPacket("s2", 5, "payload_b")

    # These should be ordered by SHA-256 of payload
    result = sequence_stream_batch([p1, p2])

    # payload_a SHA-256 < payload_b SHA-256 lexicographically
    expected_order = ["s1", "s2"]
    actual_order = [pkt.stream_id for pkt in result]
    assert actual_order == expected_order
